# Commercial partnerships become Programme Economy-native, with different structures and persistent reputation.
commercial_block = r'''function managerCommercialRep(){const rows=safe(()=>importManagerResults().flatMap(x=>x.rows),[]),wins=rows.filter(x=>Number(x.place)===1).length,records=rows.filter(x=>(x.achievements||[]).some(a=>['WR','NR'].includes(a))).length;return clamp(20+wins*2+records*3+Number(s?.medals?.g||0)*5+Number(s?.medals?.s||0)*3+Number(s?.medals?.b||0)*2,0,100)}
function commercialOffers(){const p=prog(),commercialRep=clamp(Number(p.commercial?.reputation??50),0,100),scale=clamp(costFactor()*inf(),.72,2.2)*(.9+commercialRep/500),managerRep=managerCommercialRep(),fac3=['sprint','field','recovery'].every(k=>feff(k)>=3),raw=[
 {id:'community',name:'Stride Community Sport',structure:'guaranteed',risk:'LOW',upfront:520000,bonus:0,goal:'Guaranteed programme support with no results target.',boardView:'Low risk. Useful when the programme needs certainty.',eligible:true},
 {id:'podium',name:'Apex Performance',structure:'tiered',risk:'MEDIUM',upfront:180000,bonus:800000,goal:'Performance ladder: one international podium unlocks a partial payment; three unlock the full bonus.',boardView:'Balanced upside without putting the core programme at risk.',eligible:true},
 {id:'championship',name:'Vanguard Athletics',structure:'championship',risk:'HIGH',upfront:300000,bonus:1050000,goal:'Earn at least one medal at a championship or Olympic event after signing.',boardView:'A strong offer if the squad is genuinely ready for major-event pressure.',eligible:managerRep>=30},
 {id:'prestige',name:'Summit Elite',structure:'prestige',risk:'HIGH',upfront:150000,bonus:1500000,goal:'Win two international events after signing. Requires manager reputation 45 and all three performance facilities at Level 3 or higher.',boardView:'Highest upside, but missing the target will hurt commercial confidence.',eligible:managerRep>=45&&fac3}
 ];return raw.map(o=>({...o,upfront:Math.round(o.upfront*scale/5000)*5000,bonus:Math.round(o.bonus*scale/5000)*5000,commercialReputation:commercialRep}))}
function commercialProgress(deal){if(!deal)return{met:false,payout:0,label:'No agreement'};const legacy=!Number(deal.modelVersion||0),podiums=Number(deal.podiums||0),wins=Number(deal.wins||0),champ=Number(deal.championshipMedals||0),bonus=Number(deal.bonus||0);if(deal.id==='community'||deal.structure==='guaranteed')return{met:true,payout:0,label:'Guaranteed funding secured'};if(deal.id==='podium'||deal.structure==='tiered'){const threshold=3,payout=podiums>=3?bonus:legacy?0:podiums===2?Math.round(bonus*.55/5000)*5000:podiums===1?Math.round(bonus*.25/5000)*5000:0;return{met:podiums>=threshold,payout,label:`${podiums} / ${threshold} international podiums`}}if(deal.id==='championship'||deal.structure==='championship')return{met:champ>=1,payout:champ>=1?bonus:0,label:`${champ} / 1 championship medals`};const target=legacy?1:2,payout=wins>=target?bonus:legacy?0:wins===1?Math.round(bonus*.45/5000)*5000:0;return{met:wins>=target,payout,label:`${wins} / ${target} international wins`}}
function signCommercial(id){const m=safe(()=>managementState(),null),p=prog();if(!m||wk()>=48)return false;m.sponsors??={};if(m.sponsors[yr()])return false;const offer=commercialOffers().find(x=>String(x.id)===String(id));if(!offer?.eligible)return false;m.sponsors[yr()]={...offer,modelVersion:2,season:yr(),signedWeek:wk(),podiums:0,wins:0,championshipMedals:0,internationalStarts:0,seen:{},commercialSeen:{},settled:false};post(offer.upfront,`${offer.name} commercial partnership`,'Sponsorship',{commercial:true,structure:offer.structure});p.commercial.history.push({season:yr(),week:wk(),partner:offer.name,type:'signed',structure:offer.structure,guaranteed:offer.upfront,potential:offer.bonus});p.commercial.history=p.commercial.history.slice(-80);mail('board',`Commercial partnership agreed: ${offer.name}`,`${cash(offer.upfront)} has been added to the programme. ${offer.goal} Potential performance payment: ${cash(offer.bonus)}. Guaranteed funding will not be clawed back if the target is missed.`,'info');saveNow();drawFinance2();return true}
function settleCommercial(){const m=safe(()=>managementState(),null),p=prog(),deal=m?.sponsors?.[yr()];if(!deal||deal.settled)return;const progress=commercialProgress(deal),payout=Number(progress.payout||0);deal.settled=true;deal.paidBonus=payout;deal.targetMet=!!progress.met;if(payout)post(payout,`${deal.name} performance payment`,'Sponsorship',{commercial:true,structure:deal.structure||deal.id});const high=(deal.risk||'').toUpperCase()==='HIGH',repDelta=deal.id==='community'?1:progress.met?4:payout>0?1:high?-5:-3,trustDelta=deal.id==='community'?1:progress.met?2:payout>0?0:high?-4:-2;p.commercial.reputation=clamp(Number(p.commercial.reputation??50)+repDelta,0,100);p.boardTrust=clamp(Number(p.boardTrust||65)+trustDelta,0,100);p.commercial.history.push({season:yr(),week:wk(),partner:deal.name,type:'settled',met:!!progress.met,payout,commercialReputation:p.commercial.reputation});p.commercial.history=p.commercial.history.slice(-80);mail('board',`Commercial review: ${deal.name}`,`${progress.met?'Target met.':payout>0?'Partial performance payment earned.':'Target missed.'} Performance payment: ${cash(payout)}. Guaranteed funding remains with the programme. Commercial reputation is now ${Math.round(p.commercial.reputation)}/100.`,'review');saveNow()}
function commercialPanel(){const p=prog(),deal=safe(()=>managementState().sponsors?.[yr()],null),offers=commercialOffers(),closed=wk()>=48,rep=Math.round(Number(p.commercial?.reputation??50));if(deal){const pr=commercialProgress(deal);return`<section class="pe-card"><div class="pe-card-head"><strong>Commercial Partnership</strong><span>Commercial reputation ${rep}/100</span></div><div class="pe-card-body"><div class="pe-commercial-current"><div><small>PARTNER</small><strong>${esc(deal.name)}</strong><p>${esc(deal.goal)}</p></div><div><small>GUARANTEED FUNDING</small><strong>${cash(deal.upfront)}</strong><p>Received in Week ${Number(deal.signedWeek)||'—'} · ${esc(deal.risk||'Standard')} risk.</p></div><div><small>PERFORMANCE POSITION</small><strong>${cash(deal.settled?deal.paidBonus||0:pr.payout||0)}</strong><p>${deal.settled?'Final payment':'Currently earned if the season ended now'} · ${esc(pr.label)}</p></div></div><div class="pe-commercial-progress"><span>International podiums <b>${Number(deal.podiums||0)}</b></span><span>International wins <b>${Number(deal.wins||0)}</b></span><span>Championship medals <b>${Number(deal.championshipMedals||0)}</b></span></div></div></section>`}return`<section class="pe-card"><div class="pe-card-head"><strong>Commercial Partnerships</strong><span>${closed?'Signing window closed':`Commercial reputation ${rep}/100`}</span></div><div class="pe-card-body"><div class="pe-sponsors">${offers.map(o=>`<article class="pe-sponsor ${o.risk.toLowerCase()}"><header><div><small>${esc(o.structure.toUpperCase())}</small><h3>${esc(o.name)}</h3></div><b class="pe-offer-risk">${esc(o.risk)} RISK</b></header><p>${esc(o.goal)}</p><div><span><small>Guaranteed</small><strong>${cash(o.upfront)}</strong></span><span><small>Maximum upside</small><strong>${cash(o.bonus)}</strong></span></div><p class="pe-offer-view"><b>Board view</b>${esc(o.boardView)}</p><button class="btn secondary" data-commercial="${esc(o.id)}" ${closed||!o.eligible?'disabled':''}>${closed?'SIGNING CLOSED':!o.eligible?'REQUIREMENTS NOT MET':'REVIEW & SIGN'}</button></article>`).join('')}</div><p class="pe-note">One commercial agreement can be signed each season. Guaranteed funding is never clawed back. High-risk deals can affect commercial reputation and board confidence if the performance target is missed.</p></div></section>`}
function income()'''
