# Board interventions and performance-funding negotiations.
board_runtime = r'''function seasonRank(){const i=Number(safe(()=>nationRanks().findIndex(x=>x[0]===nation()),-1));return i>=0?i+1:8}
function seasonInternationalPodiums(){return safe(()=>importManagerResults().filter(x=>Number(x.season)===yr()&&!x.national).flatMap(x=>x.rows||[]).filter(r=>Number(r.place)<=3).length,0)}
function ensureBoardMandate(p=prog()){const g=p.governance;g.mandateHistory??=[];if(g.mandate&&Number(g.mandate.season)===yr())return g.mandate;if(g.mandate&&Number(g.mandate.season)!==yr())g.mandate=null;if(wk()>10||g.mandateHistory.some(x=>Number(x.season)===yr()))return null;const rank=seasonRank(),x=snap(p),eligible=Number(p.boardTrust||0)>=50&&x.health!=='critical',advance=Math.round(indexedGrant()*.08/5000)*5000,targetRank=Math.max(1,rank-1),targetPodiums=rank<=4?3:2;g.mandate={id:`mandate-${yr()}`,season:yr(),status:'open',offeredWeek:wk(),deadlineWeek:10,rankAtOffer:rank,eligible,advance,targetRank,targetPodiums};mail('board','Annual funding mandate available',`The federation is prepared to discuss a performance-linked advance of ${cash(advance)}. Accepting it would set a season target of nation rank #${targetRank} or better and ${targetPodiums} international podiums. The advance is never clawed back, but missing the mandate will reduce board confidence and trigger temporary spending controls.`,'review');return g.mandate}
function chooseBoardMandate(choice,p=prog()){const g=p.governance,m=ensureBoardMandate(p);if(!m||m.status!=='open')return false;if(choice==='baseline'){m.status='baseline';m.resolvedWeek=wk();p.boardTrust=clamp(Number(p.boardTrust||65)+1,0,100);g.mandateHistory.push({...m,outcome:'baseline'});mail('board','Funding mandate: baseline plan confirmed','The programme will operate on its normal federation allocation with no additional performance condition attached.','info')}else if(choice==='accelerator'){if(!m.eligible){toastNow('The board will not approve a performance advance in the current financial position');return false}m.status='active';m.acceptedWeek=wk();post(m.advance,'Federation performance advance','Federation',{mandate:true});mail('board','Performance funding mandate agreed',`${cash(m.advance)} has been released immediately. The season target is nation rank #${m.targetRank} or better and ${m.targetPodiums} international podiums. The funding is not repayable, but missing the mandate will reduce board confidence.`,'review')}else return false;saveNow();drawFinance2();return true}
function settleBoardMandate(p=prog()){const g=p.governance,m=g.mandate;if(!m||Number(m.season)!==yr()||m.status==='settled')return;if(m.status==='open'){m.status='baseline';g.mandateHistory.push({...m,outcome:'expired-baseline'});return}if(m.status!=='active')return;const rank=seasonRank(),podiums=seasonInternationalPodiums(),met=rank<=Number(m.targetRank)&&podiums>=Number(m.targetPodiums);m.status='settled';m.finalRank=rank;m.finalPodiums=podiums;m.met=met;m.settledWeek=wk();if(met){p.boardTrust=clamp(Number(p.boardTrust||65)+6,0,100);mail('board','Performance mandate achieved',`The programme finished at nation rank #${rank} with ${podiums} international podiums. The federation considers the performance advance well used; board confidence has increased.`,'review')}else{p.boardTrust=clamp(Number(p.boardTrust||65)-10,0,100);boardControl(p,8,'performance',`Missed ${yr()} performance funding mandate`);mail('board','Performance mandate missed',`The programme finished at nation rank #${rank} with ${podiums} international podiums, below the agreed mandate. The advance is not clawed back, but board confidence has fallen and expansion spending is restricted for eight weeks.`,'review')}g.mandateHistory.push({...m,outcome:met?'met':'missed'});g.mandateHistory=g.mandateHistory.slice(-40)}
function createBoardIntervention(p,x=snap(p),reason='financial pressure'){const g=p.governance;const existing=g.intervention;if(existing?.status==='pending')return existing;if(cw()-Number(g.lastControl||0)<12)return null;const level=x.health==='critical'||Number(s.funding)<0?'critical':'recovery';g.lastControl=cw();g.intervention={id:`board-${cw()}-${level}`,status:'pending',level,reason,createdCareerWeek:cw(),deadlineCareerWeek:cw()+3,runway:Math.max(0,Math.round(x.runway)),projected:Number(x.projected||0),weekly:Number(x.weekly.total||0)};mail('board',level==='critical'?'Board intervention: programme stabilisation required':'Board intervention: recovery plan required',`The programme is under ${level==='critical'?'critical':'material'} financial pressure. A response is required in Finance → Board within three weeks. You can accept a recovery plan, ring-fence current athlete support, or request federation stabilisation funding. Ignoring the request will result in imposed controls.`,'review');return g.intervention}
function respondBoard(choice,p=prog()){const g=p.governance,x=snap(p),i=g.intervention;if(!i||i.status!=='pending')return false;let label='',grant=0,weeks=0,trust=0;if(choice==='recovery'){label='Manager-led recovery plan';weeks=8;trust=5;boardControl(p,weeks,'recovery','Manager-led recovery plan')}else if(choice==='protect'){label='Athlete programme protection';grant=Math.round(Number(x.weekly.athlete||0)*4/5000)*5000;weeks=10;trust=1;if(grant)post(grant,'Federation athlete programme protection','Federation',{intervention:true});boardControl(p,weeks,'protected-programme','Protect existing athlete programme')}else if(choice==='support'){label='Federation stabilisation support';grant=Math.ceil(Math.max(Number(x.weekly.total||0)*6,Math.abs(Math.min(0,Number(s.funding||0)))+Number(x.weekly.total||0)*4)/10000)*10000;weeks=12;trust=-5;if(grant)post(grant,'Federation stabilisation support','Federation',{intervention:true,emergency:true});boardControl(p,weeks,'stabilisation','Federation stabilisation support')}else return false;p.boardTrust=clamp(Number(p.boardTrust||65)+trust,0,100);i.status='resolved';i.choice=choice;i.outcome=label;i.resolvedCareerWeek=cw();i.grant=grant;i.controlWeeks=weeks;g.history.push({...i});g.history=g.history.slice(-80);mail('board',`Board response agreed: ${label}`,`${grant?`${cash(grant)} has been released. `:''}Expansion spending will be controlled for ${weeks} weeks while existing athlete and staff commitments continue. Board financial confidence is now ${Math.round(p.boardTrust)}/100.`,'review');saveNow();drawFinance2();return true}
function boardWeek(p,x=snap(p)){const g=p.governance,c=activeBoardControl(p);if(c&&cw()+1>=Number(c.endCareerWeek||0)&&!c.reviewNotified){c.reviewNotified=true;const better=['healthy','watch'].includes(x.health);p.boardTrust=clamp(Number(p.boardTrust||65)+(better?3:-4),0,100);mail('board',better?'Board controls approaching release':'Board controls remain under review',better?'The programme has stabilised. Expansion authority will return when the current control period ends.':'The control period is ending but the budget remains under pressure. Further intervention may follow if the position does not improve.','review')}
 const pending=g.intervention;if(pending?.status==='pending'&&cw()>=Number(pending.deadlineCareerWeek||0)){const grant=Number(s.funding)<0?Math.ceil((Math.abs(Number(s.funding))+Number(x.weekly.total||0)*4)/10000)*10000:0;if(grant)post(grant,'Imposed federation liquidity support','Federation',{intervention:true,imposed:true});p.boardTrust=clamp(Number(p.boardTrust||65)-8,0,100);boardControl(p,12,'imposed','Board-imposed stabilisation controls');pending.status='imposed';pending.choice='imposed';pending.grant=grant;pending.resolvedCareerWeek=cw();g.history.push({...pending});g.history=g.history.slice(-80);mail('board','Federation imposes stabilisation controls',`${grant?`${cash(grant)} has been released to protect existing commitments. `:''}The response deadline passed without an agreed plan. Expansion spending is restricted for twelve weeks and board confidence has fallen.`,'review')}
 if(!g.intervention||g.intervention.status!=='pending'){if(x.health==='critical'||x.health==='restricted')createBoardIntervention(p,x,`${x.health} financial health`);else if(Number(p.boardTrust||65)<30)createBoardIntervention(p,x,'low board confidence')}
 ensureBoardMandate(p)}
function applyGovernance(p,x=snap(p)){p.governance??={lastHealth:p.health||'healthy',lastNotice:0,lastControl:0,history:[],mandateHistory:[]};const g=p.governance,prev=g.lastHealth||'healthy',now=x.health,canNotice=cw()-Number(g.lastNotice||0)>=3;if(prev!==now&&canNotice){g.lastNotice=cw();if(now==='watch')mail('board','Budget position moved to watch',`The programme now has roughly ${Math.max(0,Math.round(x.runway))} weeks of operating runway. Existing commitments are secure, but the board expects new spending to be considered against the season-end forecast.`,'review');else if(['restricted','critical'].includes(now))createBoardIntervention(p,x,`${now} financial health`);else if(now==='healthy'&&['watch','restricted','critical'].includes(prev))mail('board','Programme finances returned to a healthy position',`Available funding and current commitments now provide ${Math.max(0,Math.round(x.runway))} weeks of operating runway. Existing board controls will expire on their stated timetable.`,'review')}if(Number(p.boardTrust||65)<30)createBoardIntervention(p,x,'low board confidence');g.lastHealth=now}

function runEconomy(){const p=prog();if(Number(p.lastWeekly)===cw())return;p.lastWeekly=cw();facilityWeek(p);const w=weekly(p);if(w.athlete)post(-w.athlete,'Athlete programme payroll','Athlete Contracts',{recurring:true});if(w.staff)post(-w.staff,'Performance staff payroll','Staff',{recurring:true});if(w.facilities)post(-w.facilities,'National facility upkeep','Facilities',{recurring:true});if(w.operations)post(-w.operations,'Performance operations','Operations',{recurring:true});athleteExpiries(p);staffExpiries(p);const x=snap(p);if(x.health==='critical')p.boardTrust=clamp(Number(p.boardTrust||65)-.4,0,100);else if(x.health==='healthy')p.boardTrust=clamp(Number(p.boardTrust||65)+.08,0,100);applyGovernance(p,x);boardWeek(p,x)}
function dialog()'''
text = sub_once(text, r"function applyGovernance\(p,x=snap\(p\)\)\{.*?\nfunction dialog\(\)", board_runtime, 'board governance runtime')

# Add a dedicated Board finance view and route all actions through Programme Economy.
board_ui = r'''function boardPanel(){const p=prog(),x=snap(p),g=p.governance;ensureBoardMandate(p);if(!g.intervention?.status||g.intervention.status!=='pending')boardWeek(p,x);const i=g.intervention?.status==='pending'?g.intervention:null,c=activeBoardControl(p),m=g.mandate&&Number(g.mandate.season)===yr()?g.mandate:null,last=(g.history||[]).slice(-1)[0];return`<div class="pe-board-grid"><section class="pe-card"><div class="pe-card-head"><strong>Board Authority</strong><span>Confidence ${Math.round(p.boardTrust)}/100</span></div><div class="pe-card-body"><div class="pe-board-status"><div><small>FINANCIAL HEALTH</small><strong class="pe-health ${x.health}">${esc(x.health.toUpperCase())}</strong><span>${Math.max(0,Math.round(x.runway))} weeks runway · ${cash(x.projected)} projected season end</span></div><div><small>EXPANSION AUTHORITY</small><strong>${c?`${Math.max(0,Number(c.endCareerWeek)-cw())}W CONTROL`:'NORMAL'}</strong><span>${c?esc(c.reason):'New programme investment remains under your authority.'}</span></div></div>${i?`<div class="pe-board-alert ${i.level}"><small>BOARD RESPONSE REQUIRED · ${Math.max(0,Number(i.deadlineCareerWeek)-cw())} WEEKS</small><h3>${i.level==='critical'?'Programme stabilisation':'Financial recovery plan'}</h3><p>The board wants a clear response before it imposes its own plan. Existing athlete and staff agreements remain protected whichever route you choose.</p><div class="pe-board-options"><button data-board-choice="recovery"><strong>RUN A RECOVERY PLAN</strong><span>No extra funding · 8 weeks expansion control · board confidence improves now</span></button><button data-board-choice="protect"><strong>PROTECT ATHLETE SUPPORT</strong><span>Four weeks of current athlete payroll funded · 10 weeks expansion control</span></button><button data-board-choice="support"><strong>REQUEST STABILISATION</strong><span>Largest cash injection · 12 weeks expansion control · board confidence falls</span></button></div></div>`:`<div class="pe-board-clear"><strong>No board intervention outstanding</strong><span>${last?`Last intervention: ${esc(last.outcome||last.reason||'resolved')}.`:'The federation has not imposed a financial intervention in this career.'}</span></div>`}</div></section><aside class="pe-card"><div class="pe-card-head"><strong>Annual Funding Mandate</strong><span>${m?.status==='active'?'Active':m?.status==='open'?'Decision open':'Standard funding'}</span></div><div class="pe-card-body">${m?.status==='open'?`<div class="pe-mandate"><small>PERFORMANCE-LINKED ADVANCE</small><strong>${cash(m.advance)}</strong><p>Take additional federation money now and commit to finishing at nation rank #${m.targetRank} or better with ${m.targetPodiums} international podiums.</p><div class="pe-mandate-options"><button class="btn ghost" data-mandate-choice="baseline">KEEP BASELINE PLAN</button><button class="btn secondary" data-mandate-choice="accelerator" ${m.eligible?'':'disabled'}>ACCEPT ${cash(m.advance)} ADVANCE</button></div><span>${m.eligible?'Missing the target never triggers repayment, but it will reduce board confidence and impose eight weeks of expansion controls.':'The board will not release an advance while confidence or financial health is too weak.'}</span></div>`:m?.status==='active'?`<div class="pe-mandate"><small>ACTIVE PERFORMANCE MANDATE</small><strong>${cash(m.advance)} RECEIVED</strong><p>Target: rank #${m.targetRank} or better and ${m.targetPodiums} international podiums.</p><div class="pe-mandate-progress"><span>Current rank <b>#${seasonRank()}</b></span><span>International podiums <b>${seasonInternationalPodiums()} / ${m.targetPodiums}</b></span></div></div>`:`<div class="pe-board-clear"><strong>Baseline federation plan</strong><span>No additional performance advance is attached to the current season.</span></div>`}</div></aside></div>`}
function fbody(){return UI.finance==='income'?income():UI.finance==='expenditure'?expenditure():UI.finance==='contracts'?contracts():UI.finance==='facilities'?facilities():UI.finance==='forecast'?forecast():UI.finance==='board'?boardPanel():UI.finance==='history'?`<section class="pe-card"><div class="pe-card-head"><strong>Transaction History</strong><span>Every tracked programme movement</span></div>${hist(120)}</section>`:overview()}
function drawFinance2(){const root=document.getElementById('finance');if(!root)return;prog();root.innerHTML=`<div class="pe-shell" data-am-ui-screen="programme-economy-v2"><header class="pe-head"><div><small>${nlabel().toUpperCase()} · PROGRAMME OPERATIONS</small><h1>Finance</h1><p>Run the programme, protect commitments and decide where the next pound matters.</p></div><div class="pe-head-actions"><span>${cash(s.funding)} AVAILABLE</span><button class="btn secondary" data-staff>STAFF MARKET</button></div></header>${kpis()}<nav class="pe-tabs">${[['overview','Overview'],['income','Income'],['expenditure','Expenditure'],['contracts','Contracts'],['facilities','Facilities'],['forecast','Forecast'],['board','Board'],['history','History']].map(([k,l])=>`<button class="${UI.finance===k?'on':''}" data-tab="${k}">${l}</button>`).join('')}</nav><main class="pe-body">${fbody()}</main></div>`;root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{UI.finance=b.dataset.tab;drawFinance2()});root.querySelector('[data-staff]')?.addEventListener('click',()=>view('staff'));root.querySelectorAll('[data-ar]').forEach(b=>b.onclick=()=>openAthlete(b.dataset.ar,true));root.querySelectorAll('[data-sr]').forEach(b=>b.onclick=()=>openStaff(b.dataset.sr,s.coaches?.[b.dataset.sr]?.id,true));root.querySelectorAll('[data-fu]').forEach(b=>b.onclick=()=>upgrade(b.dataset.fu));root.querySelectorAll('[data-fs]').forEach(b=>b.onclick=()=>service(b.dataset.fs));root.querySelectorAll('[data-fi-full]').forEach(b=>b.onclick=()=>resolveFacilityIncident(b.dataset.fiFull,'full'));root.querySelectorAll('[data-fi-temp]').forEach(b=>b.onclick=()=>resolveFacilityIncident(b.dataset.fiTemp,'temporary'));root.querySelectorAll('[data-fi-defer]').forEach(b=>b.onclick=()=>resolveFacilityIncident(b.dataset.fiDefer,'defer'));root.querySelectorAll('[data-commercial]').forEach(b=>b.onclick=()=>{const offer=commercialOffers().find(x=>String(x.id)===String(b.dataset.commercial));if(!offer||!offer.eligible||wk()>=48)return;if(!safe(()=>confirm(`Sign ${offer.name}? ${cash(offer.upfront)} is guaranteed now; up to ${cash(offer.bonus)} remains performance-linked.`),true))return;signCommercial(offer.id)});root.querySelectorAll('[data-board-choice]').forEach(b=>b.onclick=()=>{if(!safe(()=>confirm('Confirm this board response? The spending-control period will begin immediately.'),true))return;respondBoard(b.dataset.boardChoice)});root.querySelectorAll('[data-mandate-choice]').forEach(b=>b.onclick=()=>{if(b.disabled)return;if(b.dataset.mandateChoice==='accelerator'&&!safe(()=>confirm('Accept the performance-linked federation advance and its season target?'),true))return;chooseBoardMandate(b.dataset.mandateChoice)});safe(()=>window.AthleticsUI?.registerScreen?.('finance',{status:'candidate',replacement:'programme-economy-v2'}),null)}
function skpis()'''
text = sub_once(text, r"function fbody\(\)\{.*?\nfunction skpis\(\)", board_ui, 'board finance UI')

# Surface board pressure first in the existing Home Manager Agenda, without creating another notification authority.
home_summary = r'''function homeSummary(){
 const p=prog(),x=snap(p),g=p.governance;ensureBoardMandate(p);const deal=safe(()=>managementState().sponsors?.[yr()],null),facilityIssues=Object.entries(p.facilities||{}).filter(([,f])=>f?.incident||Number(f?.condition||100)<70),athleteDue=Object.values(p.athleteContracts||{}).filter(c=>c?.state==='active'&&weeks(c)<=12).length,staffDue=Object.values(p.staffContracts||{}).filter(c=>c?.state==='active'&&weeks(c)<=12).length,expiring=athleteDue+staffDue,commercialOpen=!deal&&wk()<48&&safe(()=>commercialOffers().some(o=>o.eligible),false),restrictionWeeks=Math.max(0,Number(p.restrictionUntil||0)-cw()),intervention=g.intervention?.status==='pending'?g.intervention:null,mandate=g.mandate&&Number(g.mandate.season)===yr()?g.mandate:null,priorities=[];
 if(intervention)priorities.push({tab:'board',severity:intervention.level==='critical'?'critical':'high',title:intervention.level==='critical'?'Board intervention requires a response':'Board recovery plan requires a response',meta:`Decision due in ${Math.max(0,Number(intervention.deadlineCareerWeek)-cw())} weeks · expansion authority at risk`});
 if(!intervention&&x.health!=='healthy')priorities.push({tab:'forecast',severity:x.health==='critical'?'critical':x.health==='restricted'?'high':'medium',title:x.health==='critical'?'Financial controls active':x.health==='restricted'?'Protect programme commitments':'Budget position needs watching',meta:`${Math.max(0,Math.round(x.runway))} weeks runway · projected ${cash(x.projected)} season end`});
 if(mandate?.status==='open')priorities.push({tab:'board',severity:'opportunity',title:'Performance funding mandate available',meta:`${cash(mandate.advance)} advance available with a season performance target`});
 if(facilityIssues.length)priorities.push({tab:'facilities',severity:facilityIssues.some(([,f])=>f.incident)?'high':'medium',title:`${facilityIssues.length} facilit${facilityIssues.length===1?'y':'ies'} need attention`,meta:facilityIssues.some(([,f])=>f.incident)?'Operational decision outstanding':'Condition is reducing effective performance'});
 if(expiring)priorities.push({tab:'contracts',severity:'medium',title:`${expiring} programme contract${expiring===1?'':'s'} approaching expiry`,meta:'Athlete and staff agreements inside 12 weeks'});
 if(commercialOpen)priorities.push({tab:'income',severity:'opportunity',title:'Commercial partnership available',meta:'Different guaranteed/performance structures are open for review'});
 return{health:x.health,available:Number(s.funding||0),weekly:Number(x.weekly.total||0),projected:Number(x.projected||0),runway:Number(x.runway||0),boardTrust:Number(p.boardTrust||0),restricted:restricted(p),restrictionWeeks,expiring,athleteDue,staffDue,facilityIssues:facilityIssues.length,commercialOpen,commercialPartner:deal?.name||null,commercialReputation:Number(p.commercial?.reputation??50),boardIntervention:intervention?.level||null,mandateStatus:mandate?.status||null,priorities};
}
function openFinanceView(tab='overview'){const valid=['overview','income','expenditure','contracts','facilities','forecast','board','history'];UI.finance=valid.includes(tab)?tab:'overview';try{view('finance')}catch(_){}requestAnimationFrame(()=>{try{drawFinance2()}catch(_){}});return UI.finance}

function marketCard'''
text = sub_once(text, r"function homeSummary\(\)\{.*?\nfunction marketCard", home_summary, 'home board and commercial priorities')

# Settle the board mandate before the legacy season authority rolls to the next year, and make Programme Economy the sponsorship settlement authority.
text = replace_once(
    text,
    "p.boardTrust=clamp(p.boardTrust+seasonDelta+efficiency,0,100);const out=OLD.endSeason.apply(this,arguments);",
    "p.boardTrust=clamp(p.boardTrust+seasonDelta+efficiency,0,100);settleBoardMandate(p);const out=OLD.endSeason.apply(this,arguments);",
    'settle board mandate before rollover'
)
text = replace_once(
    text,
    "prog();recordFinance=record;signSponsor=signCommercial;facilityLevel=feff;",
    "prog();recordFinance=record;signSponsor=signCommercial;settleSponsor=settleCommercial;facilityLevel=feff;",
    'commercial settlement authority'
)
text = replace_once(
    text,
    "inflationIndex,indexedGrant,homeSummary,openFinanceView,renderFinance:drawFinance2,renderStaff:drawStaff2,debug:()=>({nation:nation(),cash:s.funding,snapshot:snap(),athleteContracts:Object.keys(prog().athleteContracts).length,staffContracts:Object.keys(prog().staffContracts).length})",
    "inflationIndex,indexedGrant,homeSummary,openFinanceView,commercial:{offers:commercialOffers,progress:commercialProgress,settle:settleCommercial},board:{respond:respondBoard,chooseMandate:chooseBoardMandate,ensureMandate:ensureBoardMandate,control:()=>activeBoardControl(prog())},renderFinance:drawFinance2,renderStaff:drawStaff2,debug:()=>({nation:nation(),cash:s.funding,snapshot:snap(),board:prog().governance,commercial:prog().commercial,athleteContracts:Object.keys(prog().athleteContracts).length,staffContracts:Object.keys(prog().staffContracts).length})",
    'export commercial and board authority'
)
p.write_text(text, encoding='utf-8')

# Board/commercial presentation styles.
p = Path('styles/programme-economy-v1.css')
css = p.read_text(encoding='utf-8')
marker = '/* Programme Economy V2 — board and commercial pressure */'
if marker not in css:
    css += r'''

/* Programme Economy V2 — board and commercial pressure */
.pe-sponsors{grid-template-columns:repeat(2,minmax(0,1fr))}.pe-sponsor header{display:flex;align-items:flex-start;justify-content:space-between;gap:8px}.pe-offer-risk{flex:0 0 auto;padding:4px 6px;border:1px solid #31536a;border-radius:6px;color:#9bb8c9;font-size:6px;letter-spacing:.07em}.pe-sponsor.high .pe-offer-risk{border-color:#765146;color:#e8b390}.pe-sponsor.medium .pe-offer-risk{border-color:#6d613a;color:#dcc77e}.pe-offer-view{padding:8px;border:1px solid #1c374a;border-radius:7px;background:#07151f}.pe-offer-view b{display:block;margin-bottom:2px;color:#9fb4c2;font-size:7px}.pe-commercial-progress{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin-top:9px}.pe-commercial-progress span{padding:8px;border:1px solid #1d394c;border-radius:8px;background:#07151f;color:#7993a5;font-size:7px}.pe-commercial-progress b{display:block;margin-top:3px;color:#e2edf3;font-size:12px}.pe-board-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(300px,.65fr);gap:12px}.pe-board-status{display:grid;grid-template-columns:1fr 1fr;gap:8px}.pe-board-status>div{padding:11px;border:1px solid #203d51;border-radius:9px;background:#071722}.pe-board-status small,.pe-mandate small,.pe-board-alert>small{display:block;color:#718da0;font-size:7px;font-weight:950;letter-spacing:.08em}.pe-board-status strong{display:block;margin:4px 0;font-size:16px}.pe-board-status span{display:block;color:#7d97a8;font-size:8px;line-height:1.45}.pe-board-alert{margin-top:10px;padding:12px;border:1px solid #68464b;border-radius:10px;background:#211317}.pe-board-alert.recovery{border-color:#715b39;background:#211b10}.pe-board-alert>small{color:#e9a8ad}.pe-board-alert.recovery>small{color:#e2c27f}.pe-board-alert h3{margin:5px 0 4px;font-size:15px}.pe-board-alert p{margin:0;color:#aa969a;font-size:8px;line-height:1.5}.pe-board-options{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;margin-top:10px}.pe-board-options button{min-height:88px;padding:9px;border:1px solid #3a5362;border-radius:8px;background:#0a1d29;color:#e6eef3;text-align:left;cursor:pointer}.pe-board-options button:hover{border-color:#5d91af;background:#0d2636}.pe-board-options strong,.pe-board-options span{display:block}.pe-board-options strong{font-size:8px}.pe-board-options span{margin-top:4px;color:#829aa9;font-size:7px;line-height:1.4}.pe-board-clear{display:grid;gap:3px;margin-top:10px;padding:14px;border:1px solid #203d51;border-radius:9px;background:#071722}.pe-board-clear strong{font-size:10px}.pe-board-clear span{color:#7d97a8;font-size:8px;line-height:1.45}.pe-mandate>strong{display:block;margin:5px 0;font-size:22px}.pe-mandate p{margin:0;color:#839caa;font-size:8px;line-height:1.5}.pe-mandate>span{display:block;margin-top:8px;color:#7891a2;font-size:7px;line-height:1.45}.pe-mandate-options{display:grid;grid-template-columns:1fr 1.35fr;gap:6px;margin-top:10px}.pe-mandate-options .btn{min-height:39px;font-size:7px}.pe-mandate-progress{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:10px}.pe-mandate-progress span{padding:9px;border:1px solid #1f3b4e;border-radius:8px;background:#071722;color:#7891a2;font-size:7px}.pe-mandate-progress b{display:block;margin-top:3px;color:#e2edf3;font-size:12px}@media(max-width:980px){.pe-board-grid{grid-template-columns:1fr}.pe-board-options{grid-template-columns:1fr}.pe-sponsors{grid-template-columns:1fr}}@media(max-width:700px){.pe-board-status,.pe-commercial-progress,.pe-mandate-progress,.pe-mandate-options{grid-template-columns:1fr}}
'''
p.write_text(css, encoding='utf-8')

# Static gameplay contract exercised inside the existing runtime smoke.
p = Path('tools/programme-board-commercial-soak.mjs')
p.write_text(r'''import fs from 'node:fs';
import assert from 'node:assert/strict';

const src=fs.readFileSync('scripts/programme-economy-v2.js','utf8');
for(const token of [
 'function commercialProgress(deal)',
 "id:'community'",
 "id:'podium'",
 "id:'championship'",
 "id:'prestige'",
 'settleSponsor=settleCommercial',
 'function createBoardIntervention',
 'function respondBoard(choice',
 'function ensureBoardMandate',
 'function settleBoardMandate',
 "data-board-choice=\"recovery\"",
 "data-board-choice=\"protect\"",
 "data-board-choice=\"support\"",
 "data-mandate-choice=\"accelerator\"",
 "'board','Board'",
 "tab:'board'"
]) assert(src.includes(token),`Missing commercial/board contract: ${token}`);
assert(src.includes("Guaranteed funding will not be clawed back"),'Commercial guarantees must not be clawed back');
assert(src.includes("boardControl(p,8,'performance'"),'Missed performance mandate must create temporary board controls');
assert(src.includes("boardControl(p,12,'imposed'"),'Ignored board intervention must impose controls');
assert(src.includes("commercialReputation"),'Commercial reputation must persist across seasons');
console.log('Programme commercial + board pressure contract: PASS');
''',encoding='utf-8')

p = Path('tools/runtime-smoke.mjs')
smoke = p.read_text(encoding='utf-8')
smoke = replace_once(smoke, " await import('./programme-economy-soak.mjs');", " await import('./programme-economy-soak.mjs');\n await import('./programme-board-commercial-soak.mjs');", 'runtime board/commercial soak')
p.write_text(smoke, encoding='utf-8')

# iPad cache bust and visible build marker.
p = Path('scripts/ui-cutover-v1.js')
cut = p.read_text(encoding='utf-8')
cut = replace_once(cut, "const BUILD='2026.09.13-economybalance1';", "const BUILD='2026.09.13-commercialboard1';", 'commercial board build')
cut = replace_once(cut, "styles/programme-economy-v1.css?v=20260913-economyhome1", "styles/programme-economy-v1.css?v=20260913-commercialboard1", 'commercial board style cache')
cut = replace_once(cut, "scripts/programme-economy-v2.js?v=20260913-economybalance1", "scripts/programme-economy-v2.js?v=20260913-commercialboard1", 'commercial board script cache')
p.write_text(cut, encoding='utf-8')

p = Path('game.html')
html = p.read_text(encoding='utf-8')
html = replace_once(html, "scripts/ui-cutover-v1.js?v=20260913-economybalance1", "scripts/ui-cutover-v1.js?v=20260913-commercialboard1", 'commercial board cutover cache')
p.write_text(html, encoding='utf-8')
